const auth = $('Validate Telegram initData').first()?.json ?? {};
if (auth.valid !== true) return [{ json: auth }];
function asAttachmentList(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return [value];
  if (typeof value !== 'string' || !value.trim()) return [];
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && typeof parsed === 'object') return [parsed];
  } catch {}
  return [];
}
function attachmentUrl(value) {
  const attachment = typeof value === 'string' ? value : value?.url ?? value?.signedUrl ?? value?.signed_url ?? value?.path ?? value?.signedPath ?? value?.signed_path ?? value?.thumbnails?.small?.signedPath ?? value?.thumbnails?.small?.signedUrl ?? value?.thumbnails?.card_cover?.signedPath ?? value?.thumbnails?.card_cover?.signedUrl ?? '';
  const url = String(attachment).trim();
  if (url.startsWith('http://') || url.startsWith('https://')) return url;
  if (url.startsWith('/')) return 'https://proyectos.aldeapucela.org' + url;
  if (url.startsWith('download/') || url.startsWith('dltemp/')) return 'https://proyectos.aldeapucela.org/' + url;
  return '';
}
function imageUrlsFor(fields) {
  const photoField = Object.entries(fields).find(([key]) => key.toLowerCase() === 'photos')?.[1];
  return [...asAttachmentList(photoField), ...asAttachmentList(fields.photos), ...asAttachmentList(fields.Fotos), ...asAttachmentList(fields.fotos)]
    .map(attachmentUrl).filter(Boolean).filter((url, index, urls) => urls.indexOf(url) === index);
}
function photoKeysFor(fields) {
  const photoField = Object.entries(fields).find(([key]) => key.toLowerCase() === 'photos')?.[1];
  return [...asAttachmentList(photoField), ...asAttachmentList(fields.photos), ...asAttachmentList(fields.Fotos), ...asAttachmentList(fields.fotos)]
    .map((value, index) => {
      const attachment = typeof value === 'string' ? value : value ?? {};
      return String(attachment.path ?? attachment.signedPath ?? attachment.signed_path ?? attachment.url ?? attachment.signedUrl ?? attachment.signed_url ?? attachment.title ?? 'index:' + index).trim();
    })
    .filter(Boolean).filter((key, index, keys) => keys.indexOf(key) === index);
}
const now = Date.now();
const items = $input.all()
  .map(({ json }) => json.fields ?? json)
  .filter((fields) => String(fields.owner_telegram_id ?? '') === String(auth.telegram_id))
  .map((fields) => {
    const image_urls = imageUrlsFor(fields);
    const photo_keys = photoKeysFor(fields);
    const rawStatus = String(fields.status ?? 'hidden').toLowerCase();
    const expiresTimestamp = fields.expires_at ? Date.parse(String(fields.expires_at).replace(' ', 'T')) : NaN;
    const reservationTimestamp = fields.reservation_expires_at ? Date.parse(String(fields.reservation_expires_at).replace(' ', 'T')) : NaN;
    const reservationExpired = rawStatus === 'reserved' && Number.isFinite(reservationTimestamp) && reservationTimestamp <= now;
    const publicationExpired = ['available', 'reserved'].includes(rawStatus) && Number.isFinite(expiresTimestamp) && expiresTimestamp <= now;
    const status = publicationExpired ? 'expired' : reservationExpired ? 'available' : rawStatus;
    return {
      id: fields.public_id ?? fields['item-id'] ?? null,
      title: fields.title ?? '',
      description: fields.description ?? '',
      category: fields.category ?? 'Otros',
      zone: fields.zone ?? 'Valladolid',
      status,
      created_at: fields.created_at ?? fields['Created time'] ?? fields.CreatedAt ?? null,
      updated_at: fields.updated_at ?? fields['Last modified time'] ?? fields.UpdatedAt ?? null,
      expires_at: fields.expires_at ?? null,
      completed_at: fields.completed_at ?? null,
      reserved_at: reservationExpired ? null : fields.reserved_at ?? null,
      reservation_expires_at: reservationExpired ? null : fields.reservation_expires_at ?? null,
      image_url: fields.image_url || image_urls[0] || null,
      image_urls,
      photo_keys,
      owner_display_name: fields.owner_display_name ?? 'Vecindad',
      owner_username: fields.owner_username ?? fields.owner_telegram_username ?? fields.telegram_username ?? '',
      owner_telegram_id: String(fields.owner_telegram_id ?? ''),
      interest_count: Math.max(0, Number(fields.interest_count ?? 0)),
      contact_attempt_count: Math.max(0, Number(fields.contact_attempt_count ?? 0)),
      favorite_count: Math.max(0, Number(fields.favorite_count ?? 0)),
      renewal_count: Math.max(0, Math.trunc(Number(fields.renewal_count ?? 0))),
    };
  })
  .filter((item) => item.id && ['available', 'reserved', 'completed', 'expired'].includes(item.status));
return [{ json: { ok: true, items, total: items.length } }];
